function CANTOR_PAIR(a, b):
    s <- a + b
    return s*(s+1)/2 + b

function CANTOR_UNPAIR(z):
    w <- floor((sqrt(8z+1) - 1)/2)
    t <- w*(w+1)/2
    b <- z - t; a <- w - b
    return (a, b)

function RANK_DATUM(degree, conductor, root_index):
    return CANTOR_PAIR(CANTOR_PAIR(degree, conductor), root_index)

function ENUMERATE_LISTS(alphabet_size):
    length <- 0
    loop forever:
        for idx in 0 .. alphabet_size^length - 1:
            emit base-`alphabet_size` digits of idx padded to `length`
        length <- length + 1

function CENSUS_BY_CONDUCTOR(max_conductor, degree):
    census <- empty list
    for q in 1 .. max_conductor:
        append Datum(degree, q) to census
    return census

function VERIFY_CENSUS(census, k):
    if length(census) != k: return false
    if [d.conductor for d in census] != [1..k]: return false
    return (number of distinct entries == k)

function AGREE_OFF_FINITE_SET(a, b, exceptional_primes):
    exc <- set(exceptional_primes)
    ea <- {p: coeffs | (p, coeffs) in a.euler_data, p not in exc}
    eb <- {p: coeffs | (p, coeffs) in b.euler_data, p not in exc}
    return ea == eb and a.degree == b.degree and a.conductor == b.conductor

function CERTIFICATE(a, b, exceptional_primes):
    if AGREE_OFF_FINITE_SET(a, b, exceptional_primes):
        return "same L-function (strong multiplicity one)"
    return "genuinely different L-functions"
